  1→package jlsm.engine.internal;
  2→
  3→import jlsm.engine.AllocationTracking;
  4→import jlsm.engine.Engine;
  5→import jlsm.engine.EngineMetrics;
  6→import jlsm.engine.Table;
  7→import jlsm.engine.TableMetadata;
  8→import jlsm.table.JlsmSchema;
  9→
 10→import java.io.IOException;
 11→import java.nio.file.Path;
 12→import java.util.Collection;
 13→import java.util.Objects;
 14→
 15→/**
 16→ * Embedded (local filesystem) implementation of {@link Engine}.
 17→ *
 18→ * <p>
 19→ * Manages a {@link TableCatalog} for metadata persistence and a {@link HandleTracker}
 20→ * for handle lifecycle. Each table is backed by its own subdirectory containing WAL,
 21→ * SSTable, and metadata files.
 22→ *
 23→ * <p>
 24→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md},
 25→ * {@code .decisions/table-catalog-persistence/adr.md}
 26→ */
 27→final class LocalEngine implements Engine {
 28→
 29→    private final Path rootDirectory;
 30→    private final TableCatalog catalog;
 31→    private final HandleTracker handleTracker;
 32→
 33→    private LocalEngine(Builder builder) {
 34→        this.rootDirectory = Objects.requireNonNull(builder.rootDirectory,
 35→                "rootDirectory must not be null");
 36→        this.catalog = new TableCatalog(rootDirectory);
 37→        this.handleTracker = HandleTracker.builder()
 38→                .maxHandlesPerSourcePerTable(builder.maxHandlesPerSourcePerTable)
 39→                .maxHandlesPerTable(builder.maxHandlesPerTable)
 40→                .maxTotalHandles(builder.maxTotalHandles)
 41→                .allocationTracking(builder.allocationTracking)
 42→                .build();
 43→    }
 44→
 45→    /**
 46→     * Returns a new builder for constructing a LocalEngine.
 47→     *
 48→     * @return a new builder; never null
 49→     */
 50→    static Builder builder() {
 51→        return new Builder();
 52→    }
 53→
 54→    @Override
 55→    public Table createTable(String name, JlsmSchema schema) throws IOException {
 56→        Objects.requireNonNull(name, "name must not be null");
 57→        Objects.requireNonNull(schema, "schema must not be null");
 58→        if (name.isEmpty()) {
 59→            throw new IllegalArgumentException("name must not be empty");
 60→        }
 61→        throw new UnsupportedOperationException("Not implemented");
 62→    }
 63→
 64→    @Override
 65→    public Table getTable(String name) throws IOException {
 66→        Objects.requireNonNull(name, "name must not be null");
 67→        if (name.isEmpty()) {
 68→            throw new IllegalArgumentException("name must not be empty");
 69→        }
 70→        throw new UnsupportedOperationException("Not implemented");
 71→    }
 72→
 73→    @Override
 74→    public void dropTable(String name) throws IOException {
 75→        Objects.requireNonNull(name, "name must not be null");
 76→        if (name.isEmpty()) {
 77→            throw new IllegalArgumentException("name must not be empty");
 78→        }
 79→        throw new UnsupportedOperationException("Not implemented");
 80→    }
 81→
 82→    @Override
 83→    public Collection<TableMetadata> listTables() {
 84→        throw new UnsupportedOperationException("Not implemented");
 85→    }
 86→
 87→    @Override
 88→    public TableMetadata tableMetadata(String name) {
 89→        Objects.requireNonNull(name, "name must not be null");
 90→        throw new UnsupportedOperationException("Not implemented");
 91→    }
 92→
 93→    @Override
 94→    public EngineMetrics metrics() {
 95→        throw new UnsupportedOperationException("Not implemented");
 96→    }
 97→
 98→    @Override
 99→    public void close() throws IOException {
100→        throw new UnsupportedOperationException("Not implemented");
101→    }
102→
103→    /**
104→     * Builder for {@link LocalEngine}.
105→     */
106→    static final class Builder {
107→
108→        private Path rootDirectory;
109→        private int maxHandlesPerSourcePerTable = 16;
110→        private int maxHandlesPerTable = 64;
111→        private int maxTotalHandles = 1024;
112→        private AllocationTracking allocationTracking = AllocationTracking.OFF;
113→        private long memTableFlushThresholdBytes = 64L * 1024 * 1024;
114→
115→        private Builder() {
116→        }
117→
118→        Builder rootDirectory(Path rootDirectory) {
119→            this.rootDirectory = Objects.requireNonNull(rootDirectory,
120→                    "rootDirectory must not be null");
121→            return this;
122→        }
123→
124→        Builder maxHandlesPerSourcePerTable(int max) {
125→            assert max > 0 : "max must be positive";
126→            this.maxHandlesPerSourcePerTable = max;
127→            return this;
128→        }
129→
130→        Builder maxHandlesPerTable(int max) {
131→            assert max > 0 : "max must be positive";
132→            this.maxHandlesPerTable = max;
133→            return this;
134→        }
135→
136→        Builder maxTotalHandles(int max) {
137→            assert max > 0 : "max must be positive";
138→            this.maxTotalHandles = max;
139→            return this;
140→        }
141→
142→        Builder allocationTracking(AllocationTracking tracking) {
143→            this.allocationTracking = Objects.requireNonNull(tracking,
144→                    "tracking must not be null");
145→            return this;
146→        }
147→
148→        Builder memTableFlushThresholdBytes(long bytes) {
149→            assert bytes > 0 : "bytes must be positive";
150→            this.memTableFlushThresholdBytes = bytes;
151→            return this;
152→        }
153→
154→        LocalEngine build() {
155→            if (rootDirectory == null) {
156→                throw new IllegalStateException("rootDirectory must be set");
157→            }
158→            return new LocalEngine(this);
159→        }
160→    }
161→}
