  1→package jlsm.engine.internal;
  2→
  3→import jlsm.engine.HandleEvictedException;
  4→import jlsm.engine.Table;
  5→import jlsm.engine.TableMetadata;
  6→import jlsm.table.DuplicateKeyException;
  7→import jlsm.table.JlsmDocument;
  8→import jlsm.table.JlsmTable;
  9→import jlsm.table.KeyNotFoundException;
 10→import jlsm.table.TableEntry;
 11→import jlsm.table.TableQuery;
 12→import jlsm.table.UpdateMode;
 13→
 14→import java.io.IOException;
 15→import java.util.Iterator;
 16→import java.util.Objects;
 17→import java.util.Optional;
 18→
 19→/**
 20→ * Local implementation of {@link Table} wrapping a {@link JlsmTable.StringKeyed} with
 21→ * handle lifecycle tracking.
 22→ *
 23→ * <p>
 24→ * Every method checks handle validity before delegating to the underlying table.
 25→ * If the handle has been evicted, a {@link HandleEvictedException} is thrown.
 26→ *
 27→ * <p>
 28→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 29→ */
 30→final class LocalTable implements Table {
 31→
 32→    private final JlsmTable.StringKeyed delegate;
 33→    private final HandleRegistration registration;
 34→    private final HandleTracker tracker;
 35→    private final TableMetadata metadata;
 36→
 37→    LocalTable(JlsmTable.StringKeyed delegate, HandleRegistration registration,
 38→               HandleTracker tracker, TableMetadata metadata) {
 39→        this.delegate = Objects.requireNonNull(delegate, "delegate must not be null");
 40→        this.registration = Objects.requireNonNull(registration, "registration must not be null");
 41→        this.tracker = Objects.requireNonNull(tracker, "tracker must not be null");
 42→        this.metadata = Objects.requireNonNull(metadata, "metadata must not be null");
 43→    }
 44→
 45→    @Override
 46→    public void create(String key, JlsmDocument doc) throws IOException {
 47→        Objects.requireNonNull(key, "key must not be null");
 48→        Objects.requireNonNull(doc, "doc must not be null");
 49→        checkValid();
 50→        throw new UnsupportedOperationException("Not implemented");
 51→    }
 52→
 53→    @Override
 54→    public Optional<JlsmDocument> get(String key) throws IOException {
 55→        Objects.requireNonNull(key, "key must not be null");
 56→        checkValid();
 57→        throw new UnsupportedOperationException("Not implemented");
 58→    }
 59→
 60→    @Override
 61→    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
 62→        Objects.requireNonNull(key, "key must not be null");
 63→        Objects.requireNonNull(doc, "doc must not be null");
 64→        Objects.requireNonNull(mode, "mode must not be null");
 65→        checkValid();
 66→        throw new UnsupportedOperationException("Not implemented");
 67→    }
 68→
 69→    @Override
 70→    public void delete(String key) throws IOException {
 71→        Objects.requireNonNull(key, "key must not be null");
 72→        checkValid();
 73→        throw new UnsupportedOperationException("Not implemented");
 74→    }
 75→
 76→    @Override
 77→    public void insert(JlsmDocument doc) throws IOException {
 78→        Objects.requireNonNull(doc, "doc must not be null");
 79→        checkValid();
 80→        throw new UnsupportedOperationException("Not implemented");
 81→    }
 82→
 83→    @Override
 84→    public TableQuery<String> query() {
 85→        checkValid();
 86→        throw new UnsupportedOperationException("Not implemented");
 87→    }
 88→
 89→    @Override
 90→    public Iterator<TableEntry<String>> scan(String fromKey, String toKey) throws IOException {
 91→        Objects.requireNonNull(fromKey, "fromKey must not be null");
 92→        Objects.requireNonNull(toKey, "toKey must not be null");
 93→        checkValid();
 94→        throw new UnsupportedOperationException("Not implemented");
 95→    }
 96→
 97→    @Override
 98→    public TableMetadata metadata() {
 99→        return metadata;
100→    }
101→
102→    @Override
103→    public void close() {
104→        tracker.release(registration);
105→    }
106→
107→    /**
108→     * Checks that this handle has not been evicted or invalidated.
109→     *
110→     * @throws HandleEvictedException if the handle is invalid
111→     */
112→    private void checkValid() {
113→        if (registration.isInvalidated()) {
114→            throw new HandleEvictedException(
115→                    registration.tableName(),
116→                    registration.sourceId(),
117→                    0,
118→                    registration.allocationSite(),
119→                    HandleEvictedException.Reason.EVICTION);
120→        }
121→    }
122→}
