  1→package jlsm.engine.internal;
  2→
  3→import jlsm.engine.AllocationTracking;
  4→import jlsm.engine.EngineMetrics;
  5→import jlsm.engine.HandleEvictedException;
  6→
  7→import java.io.Closeable;
  8→import java.io.IOException;
  9→import java.util.ArrayList;
 10→import java.util.HashMap;
 11→import java.util.LinkedHashMap;
 12→import java.util.List;
 13→import java.util.Map;
 14→import java.util.Objects;
 15→import java.util.concurrent.ConcurrentHashMap;
 16→import java.util.concurrent.atomic.AtomicBoolean;
 17→
 18→/**
 19→ * Tracks open table handles per source, enforces configurable limits, and performs
 20→ * greedy-source-first eviction under pressure.
 21→ *
 22→ * <p>
 23→ * Thread-safe: all mutable state is guarded by either ConcurrentHashMap or synchronized blocks.
 24→ *
 25→ * <p>
 26→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 27→ */
 28→final class HandleTracker implements Closeable {
 29→
 30→    private final int maxHandlesPerSourcePerTable;
 31→    private final int maxHandlesPerTable;
 32→    private final int maxTotalHandles;
 33→    private final AllocationTracking allocationTracking;
 34→    private final AtomicBoolean closed = new AtomicBoolean(false);
 35→
 36→    /**
 37→     * Map from tableName -> (sourceId -> list of registrations in insertion order).
 38→     * The outer ConcurrentHashMap provides thread-safe table-level access.
 39→     * Inner maps and lists are guarded by synchronizing on the per-table map.
 40→     */
 41→    private final ConcurrentHashMap<String, Map<String, List<HandleRegistration>>> tableHandles =
 42→            new ConcurrentHashMap<>();
 43→
 44→    private HandleTracker(Builder builder) {
 45→        assert builder.maxHandlesPerSourcePerTable > 0 : "maxHandlesPerSourcePerTable must be positive";
 46→        assert builder.maxHandlesPerTable > 0 : "maxHandlesPerTable must be positive";
 47→        assert builder.maxTotalHandles > 0 : "maxTotalHandles must be positive";
 48→        this.maxHandlesPerSourcePerTable = builder.maxHandlesPerSourcePerTable;
 49→        this.maxHandlesPerTable = builder.maxHandlesPerTable;
 50→        this.maxTotalHandles = builder.maxTotalHandles;
 51→        this.allocationTracking = Objects.requireNonNull(builder.allocationTracking,
 52→                "allocationTracking must not be null");
 53→    }
 54→
 55→    /**
 56→     * Returns a new builder for constructing a HandleTracker.
 57→     *
 58→     * @return a new builder; never null
 59→     */
 60→    static Builder builder() {
 61→        return new Builder();
 62→    }
 63→
 64→    /**
 65→     * Registers a new handle for the given table and source.
 66→     *
 67→     * @param tableName the table name; must not be null
 68→     * @param sourceId  the source identifier; must not be null
 69→     * @return a registration token that must be released when the handle is closed
 70→     */
 71→    HandleRegistration register(String tableName, String sourceId) {
 72→        Objects.requireNonNull(tableName, "tableName must not be null");
 73→        Objects.requireNonNull(sourceId, "sourceId must not be null");
 74→
 75→        final StackTraceElement[] allocationSite = switch (allocationTracking) {
 76→            case OFF, CALLER_TAG -> null;
 77→            case FULL_STACK -> Thread.currentThread().getStackTrace();
 78→        };
 79→
 80→        final HandleRegistration registration = new HandleRegistration(tableName, sourceId, allocationSite);
 81→
 82→        final Map<String, List<HandleRegistration>> sourceMap =
 83→                tableHandles.computeIfAbsent(tableName, k -> new LinkedHashMap<>());
 84→        synchronized (sourceMap) {
 85→            sourceMap.computeIfAbsent(sourceId, k -> new ArrayList<>()).add(registration);
 86→        }
 87→
 88→        return registration;
 89→    }
 90→
 91→    /**
 92→     * Releases a previously registered handle. Idempotent — releasing an already-released
 93→     * or invalidated registration is a no-op.
 94→     *
 95→     * @param registration the registration to release; must not be null
 96→     */
 97→    void release(HandleRegistration registration) {
 98→        Objects.requireNonNull(registration, "registration must not be null");
 99→
100→        final String tableName = registration.tableName();
101→        final String sourceId = registration.sourceId();
102→
103→        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.get(tableName);
104→        if (sourceMap == null) {
105→            return;
106→        }
107→        synchronized (sourceMap) {
108→            final List<HandleRegistration> regs = sourceMap.get(sourceId);
109→            if (regs == null) {
110→                return;
111→            }
112→            regs.remove(registration);
113→            if (regs.isEmpty()) {
114→                sourceMap.remove(sourceId);
115→            }
116→            if (sourceMap.isEmpty()) {
117→                tableHandles.remove(tableName);
118→            }
119→        }
120→    }
121→
122→    /**
123→     * Evicts handles if the table exceeds its handle limit, using greedy-source-first strategy.
124→     * Also checks total handle limit across all tables.
125→     *
126→     * @param tableName the table to check; must not be null
127→     */
128→    void evictIfNeeded(String tableName) {
129→        Objects.requireNonNull(tableName, "tableName must not be null");
130→
131→        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.get(tableName);
132→        if (sourceMap == null) {
133→            return;
134→        }
135→
136→        synchronized (sourceMap) {
137→            // Check per-source-per-table limits
138→            for (final Map.Entry<String, List<HandleRegistration>> entry : sourceMap.entrySet()) {
139→                final List<HandleRegistration> regs = entry.getValue();
140→                while (regs.size() > maxHandlesPerSourcePerTable) {
141→                    evictOldest(regs, HandleEvictedException.Reason.EVICTION);
142→                }
143→            }
144→
145→            // Check per-table limit
146→            int tableTotal = countTableHandles(sourceMap);
147→            while (tableTotal > maxHandlesPerTable) {
148→                evictFromGreediestSource(sourceMap, HandleEvictedException.Reason.EVICTION);
149→                tableTotal = countTableHandles(sourceMap);
150→            }
151→        }
152→
153→        // Check total limit across all tables — evict from this table's greediest source
154→        int total = countTotalHandles();
155→        while (total > maxTotalHandles) {
156→            synchronized (sourceMap) {
157→                if (countTableHandles(sourceMap) == 0) {
158→                    break;
159→                }
160→                evictFromGreediestSource(sourceMap, HandleEvictedException.Reason.EVICTION);
161→            }
162→            total = countTotalHandles();
163→        }
164→    }
165→
166→    /**
167→     * Invalidates all tracked handles with the given reason.
168→     *
169→     * @param reason the invalidation reason; must not be null
170→     */
171→    void invalidateAll(HandleEvictedException.Reason reason) {
172→        Objects.requireNonNull(reason, "reason must not be null");
173→
174→        for (final Map.Entry<String, Map<String, List<HandleRegistration>>> tableEntry : tableHandles.entrySet()) {
175→            final Map<String, List<HandleRegistration>> sourceMap = tableEntry.getValue();
176→            synchronized (sourceMap) {
177→                for (final List<HandleRegistration> regs : sourceMap.values()) {
178→                    for (final HandleRegistration reg : regs) {
179→                        reg.invalidate();
180→                    }
181→                }
182→                sourceMap.clear();
183→            }
184→        }
185→        tableHandles.clear();
186→    }
187→
188→    /**
189→     * Invalidates all tracked handles for a specific table.
190→     *
191→     * @param tableName the table name; must not be null
192→     * @param reason    the invalidation reason; must not be null
193→     */
194→    void invalidateTable(String tableName, HandleEvictedException.Reason reason) {
195→        Objects.requireNonNull(tableName, "tableName must not be null");
196→        Objects.requireNonNull(reason, "reason must not be null");
197→
198→        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.remove(tableName);
199→        if (sourceMap == null) {
200→            return;
201→        }
202→        synchronized (sourceMap) {
203→            for (final List<HandleRegistration> regs : sourceMap.values()) {
204→                for (final HandleRegistration reg : regs) {
205→                    reg.invalidate();
206→                }
207→            }
208→            sourceMap.clear();
209→        }
210→    }
211→
212→    /**
213→     * Returns a snapshot of current engine metrics.
214→     *
215→     * @return the current metrics; never null
216→     */
217→    EngineMetrics snapshot() {
218→        final Map<String, Integer> handlesPerTable = new HashMap<>();
219→        final Map<String, Map<String, Integer>> handlesPerSourcePerTable = new HashMap<>();
220→        int totalOpenHandles = 0;
221→
222→        for (final Map.Entry<String, Map<String, List<HandleRegistration>>> tableEntry : tableHandles.entrySet()) {
223→            final String tableName = tableEntry.getKey();
224→            final Map<String, List<HandleRegistration>> sourceMap = tableEntry.getValue();
225→            int tableTotal = 0;
226→            final Map<String, Integer> sourceCountMap = new HashMap<>();
227→
228→            synchronized (sourceMap) {
229→                for (final Map.Entry<String, List<HandleRegistration>> sourceEntry : sourceMap.entrySet()) {
230→                    final int count = sourceEntry.getValue().size();
231→                    if (count > 0) {
232→                        sourceCountMap.put(sourceEntry.getKey(), count);
233→                        tableTotal += count;
234→                    }
235→                }
236→            }
237→
238→            if (tableTotal > 0) {
239→                handlesPerTable.put(tableName, tableTotal);
240→                handlesPerSourcePerTable.put(tableName, Map.copyOf(sourceCountMap));
241→                totalOpenHandles += tableTotal;
242→            }
243→        }
244→
245→        final int tableCount = handlesPerTable.size();
246→        return new EngineMetrics(tableCount, totalOpenHandles, handlesPerTable, handlesPerSourcePerTable);
247→    }
248→
249→    @Override
250→    public void close() throws IOException {
251→        if (closed.compareAndSet(false, true)) {
252→            invalidateAll(HandleEvictedException.Reason.ENGINE_SHUTDOWN);
253→        }
254→    }
255→
256→    // ---- Private helpers ----
257→
258→    private static int countTableHandles(Map<String, List<HandleRegistration>> sourceMap) {
259→        int count = 0;
260→        for (final List<HandleRegistration> regs : sourceMap.values()) {
261→            count += regs.size();
262→        }
263→        return count;
264→    }
265→
266→    private int countTotalHandles() {
267→        int total = 0;
268→        for (final Map<String, List<HandleRegistration>> sourceMap : tableHandles.values()) {
269→            synchronized (sourceMap) {
270→                total += countTableHandles(sourceMap);
271→            }
272→        }
273→        return total;
274→    }
275→
276→    /**
277→     * Evicts the oldest handle from the source with the most handles (greedy-source-first).
278→     */
279→    private static void evictFromGreediestSource(Map<String, List<HandleRegistration>> sourceMap,
280→                                                  HandleEvictedException.Reason reason) {
281→        String greediest = null;
282→        int maxCount = 0;
283→        for (final Map.Entry<String, List<HandleRegistration>> entry : sourceMap.entrySet()) {
284→            final int count = entry.getValue().size();
285→            if (count > maxCount) {
286→                maxCount = count;
287→                greediest = entry.getKey();
288→            }
289→        }
290→        if (greediest == null) {
291→            return;
292→        }
293→        final List<HandleRegistration> regs = sourceMap.get(greediest);
294→        assert regs != null && !regs.isEmpty() : "greediest source must have registrations";
295→        evictOldest(regs, reason);
296→        if (regs.isEmpty()) {
297→            sourceMap.remove(greediest);
298→        }
299→    }
300→
301→    /**
302→     * Evicts the oldest (first) registration from the list and marks it invalidated.
303→     */
304→    private static void evictOldest(List<HandleRegistration> regs, HandleEvictedException.Reason reason) {
305→        assert !regs.isEmpty() : "cannot evict from empty list";
306→        final HandleRegistration victim = regs.removeFirst();
307→        victim.invalidate();
308→    }
309→
310→    /**
311→     * Builder for {@link HandleTracker}.
312→     */
313→    static final class Builder {
314→
315→        private int maxHandlesPerSourcePerTable = 16;
316→        private int maxHandlesPerTable = 64;
317→        private int maxTotalHandles = 1024;
318→        private AllocationTracking allocationTracking = AllocationTracking.OFF;
319→
320→        private Builder() {
321→        }
322→
323→        Builder maxHandlesPerSourcePerTable(int max) {
324→            assert max > 0 : "max must be positive";
325→            this.maxHandlesPerSourcePerTable = max;
326→            return this;
327→        }
328→
329→        Builder maxHandlesPerTable(int max) {
330→            assert max > 0 : "max must be positive";
331→            this.maxHandlesPerTable = max;
332→            return this;
333→        }
334→
335→        Builder maxTotalHandles(int max) {
336→            assert max > 0 : "max must be positive";
337→            this.maxTotalHandles = max;
338→            return this;
339→        }
340→
341→        Builder allocationTracking(AllocationTracking tracking) {
342→            Objects.requireNonNull(tracking, "tracking must not be null");
343→            this.allocationTracking = tracking;
344→            return this;
345→        }
346→
347→        HandleTracker build() {
348→            return new HandleTracker(this);
349→        }
350→    }
351→}
352→

  1→package jlsm.engine.internal;
  2→
  3→import jlsm.engine.TableMetadata;
  4→import jlsm.table.JlsmSchema;
  5→
  6→import java.io.Closeable;
  7→import java.io.DataInputStream;
  8→import java.io.DataOutputStream;
  9→import java.io.IOException;
 10→import java.nio.file.DirectoryStream;
 11→import java.nio.file.Files;
 12→import java.nio.file.Path;
 13→import java.time.Instant;
 14→import java.util.Collection;
 15→import java.util.Collections;
 16→import java.util.Objects;
 17→import java.util.Optional;
 18→import java.util.concurrent.ConcurrentHashMap;
 19→import java.util.concurrent.atomic.AtomicBoolean;
 20→
 21→/**
 22→ * Manages per-table directory layout, metadata persistence, and lazy table loading.
 23→ *
 24→ * <p>
 25→ * Each table lives in its own subdirectory under the engine root. The catalog scans
 26→ * the root directory on {@link #open()} to discover existing tables and builds lightweight
 27→ * metadata handles. Full table initialization is deferred until first access.
 28→ *
 29→ * <p>
 30→ * Governed by: {@code .decisions/table-catalog-persistence/adr.md}
 31→ */
 32→final class TableCatalog implements Closeable {
 33→
 34→    private static final String METADATA_FILE = "table.meta";
 35→    private static final int MAGIC = 0x4A4C534D; // "JLSM"
 36→
 37→    private final Path rootDir;
 38→    private final ConcurrentHashMap<String, TableMetadata> tables = new ConcurrentHashMap<>();
 39→    private volatile boolean loading = true;
 40→    private final AtomicBoolean closed = new AtomicBoolean(false);
 41→
 42→    /**
 43→     * Constructs a new TableCatalog for the given root directory.
 44→     *
 45→     * @param rootDir the engine root directory; must not be null
 46→     */
 47→    TableCatalog(Path rootDir) {
 48→        this.rootDir = Objects.requireNonNull(rootDir, "rootDir must not be null");
 49→    }
 50→
 51→    /**
 52→     * Opens the catalog by scanning the root directory for existing table subdirectories.
 53→     * Builds lightweight metadata handles without fully initializing tables.
 54→     * Creates the root directory if it does not exist.
 55→     *
 56→     * @throws IOException if the root directory cannot be read or is corrupt
 57→     */
 58→    void open() throws IOException {
 59→        if (!Files.exists(rootDir)) {
 60→            Files.createDirectories(rootDir);
 61→        }
 62→
 63→        try (final DirectoryStream<Path> stream = Files.newDirectoryStream(rootDir)) {
 64→            for (final Path entry : stream) {
 65→                if (!Files.isDirectory(entry)) {
 66→                    continue;
 67→                }
 68→                final String tableName = entry.getFileName().toString();
 69→                final Path metadataPath = entry.resolve(METADATA_FILE);
 70→
 71→                if (!Files.exists(metadataPath)) {
 72→                    // Partial creation cleanup: directory exists but no metadata file
 73→                    deleteDirectoryTree(entry);
 74→                    continue;
 75→                }
 76→
 77→                try {
 78→                    final TableMetadata metadata = readMetadata(tableName, metadataPath);
 79→                    tables.put(tableName, metadata);
 80→                } catch (IOException e) {
 81→                    // Corrupt metadata — clean up
 82→                    deleteDirectoryTree(entry);
 83→                }
 84→            }
 85→        }
 86→
 87→        loading = false;
 88→    }
 89→
 90→    /**
 91→     * Registers a new table by creating its subdirectory and metadata file.
 92→     *
 93→     * @param name   the table name; must not be null or empty
 94→     * @param schema the table schema; must not be null
 95→     * @return the metadata for the newly registered table
 96→     * @throws IOException if the table already exists or the directory cannot be created
 97→     */
 98→    TableMetadata register(String name, JlsmSchema schema) throws IOException {
 99→        Objects.requireNonNull(name, "name must not be null");
100→        Objects.requireNonNull(schema, "schema must not be null");
101→        if (name.isEmpty()) {
102→            throw new IllegalArgumentException("name must not be empty");
103→        }
104→
105→        if (tables.containsKey(name)) {
106→            throw new IOException("Table already exists: " + name);
107→        }
108→
109→        final Path tableDir = rootDir.resolve(name);
110→        Files.createDirectories(tableDir);
111→
112→        final Instant createdAt = Instant.now();
113→        final TableMetadata metadata = new TableMetadata(name, schema, createdAt, TableMetadata.TableState.READY);
114→
115→        writeMetadata(tableDir.resolve(METADATA_FILE), metadata);
116→
117→        final TableMetadata previous = tables.putIfAbsent(name, metadata);
118→        if (previous != null) {
119→            // Concurrent registration — clean up and throw
120→            deleteDirectoryTree(tableDir);
121→            throw new IOException("Table already exists (concurrent registration): " + name);
122→        }
123→
124→        return metadata;
125→    }
126→
127→    /**
128→     * Unregisters a table by removing its subdirectory and all contained files.
129→     *
130→     * @param name the table name; must not be null or empty
131→     * @throws IOException if the table does not exist or cannot be removed
132→     */
133→    void unregister(String name) throws IOException {
134→        Objects.requireNonNull(name, "name must not be null");
135→        if (name.isEmpty()) {
136→            throw new IllegalArgumentException("name must not be empty");
137→        }
138→
139→        final TableMetadata removed = tables.remove(name);
140→        if (removed == null) {
141→            throw new IOException("Table does not exist: " + name);
142→        }
143→
144→        final Path tableDir = rootDir.resolve(name);
145→        if (Files.exists(tableDir)) {
146→            deleteDirectoryTree(tableDir);
147→        }
148→    }
149→
150→    /**
151→     * Returns metadata for a specific table, or empty if not registered.
152→     *
153→     * @param name the table name; must not be null
154→     * @return an Optional containing the metadata, or empty if not found
155→     */
156→    Optional<TableMetadata> get(String name) {
157→        Objects.requireNonNull(name, "name must not be null");
158→        return Optional.ofNullable(tables.get(name));
159→    }
160→
161→    /**
162→     * Returns metadata for all known tables.
163→     *
164→     * @return an unmodifiable collection of table metadata; never null
165→     */
166→    Collection<TableMetadata> list() {
167→        return Collections.unmodifiableCollection(tables.values());
168→    }
169→
170→    /**
171→     * Returns the directory path for a given table.
172→     *
173→     * @param name the table name; must not be null
174→     * @return the table's subdirectory path; never null
175→     */
176→    Path tableDirectory(String name) {
177→        Objects.requireNonNull(name, "name must not be null");
178→        return rootDir.resolve(name);
179→    }
180→
181→    /**
182→     * Returns true if the catalog is still loading (scanning the root directory).
183→     *
184→     * @return true if loading is in progress
185→     */
186→    boolean isLoading() {
187→        return loading;
188→    }
189→
190→    @Override
191→    public void close() throws IOException {
192→        if (closed.compareAndSet(false, true)) {
193→            tables.clear();
194→        }
195→    }
196→
197→    // ---- Private helpers ----
198→
199→    /**
200→     * Writes table metadata to a binary file.
201→     * Format: magic (4 bytes) | schema-name (UTF) | schema-version (int) | field-count (int) | created-at-millis (long)
202→     */
203→    private static void writeMetadata(Path path, TableMetadata metadata) throws IOException {
204→        assert metadata != null : "metadata must not be null";
205→        try (final DataOutputStream out = new DataOutputStream(Files.newOutputStream(path))) {
206→            out.writeInt(MAGIC);
207→            out.writeUTF(metadata.schema().name());
208→            out.writeInt(metadata.schema().version());
209→            out.writeInt(metadata.schema().fields().size());
210→            out.writeLong(metadata.createdAt().toEpochMilli());
211→        }
212→    }
213→
214→    /**
215→     * Reads minimal metadata from a binary file. Returns a TableMetadata with LOADING state
216→     * and a skeleton JlsmSchema (name and version only, no fields).
217→     */
218→    private static TableMetadata readMetadata(String tableName, Path path) throws IOException {
219→        assert tableName != null : "tableName must not be null";
220→        assert path != null : "path must not be null";
221→        try (final DataInputStream in = new DataInputStream(Files.newInputStream(path))) {
222→            final int magic = in.readInt();
223→            if (magic != MAGIC) {
224→                throw new IOException("Invalid metadata magic: 0x" + Integer.toHexString(magic));
225→            }
226→            final String schemaName = in.readUTF();
227→            final int schemaVersion = in.readInt();
228→            final int fieldCount = in.readInt(); // read but not used for reconstruction
229→            final long createdAtMillis = in.readLong();
230→
231→            // Build skeleton schema — name and version only
232→            final JlsmSchema skeleton = JlsmSchema.builder(schemaName, schemaVersion).build();
233→            final Instant createdAt = Instant.ofEpochMilli(createdAtMillis);
234→
235→            return new TableMetadata(tableName, skeleton, createdAt, TableMetadata.TableState.LOADING);
236→        }
237→    }
238→
239→    /**
240→     * Recursively deletes a directory and all its contents.
241→     * Uses an iterative approach (depth-first via walkFileTree).
242→     */
243→    private static void deleteDirectoryTree(Path root) throws IOException {
244→        assert root != null : "root must not be null";
245→        if (!Files.exists(root)) {
246→            return;
247→        }
248→        // Walk the tree and collect paths, then delete in reverse order (children first)
249→        final java.util.List<Path> paths = new java.util.ArrayList<>();
250→        try (final var walker = Files.walk(root)) {
251→            walker.forEach(paths::add);
252→        }
253→        // Delete in reverse order so children are deleted before parents
254→        for (int i = paths.size() - 1; i >= 0; i--) {
255→            Files.deleteIfExists(paths.get(i));
256→        }
257→    }
258→}
