 1→package jlsm.engine;
 2→
 3→import java.util.Objects;
 4→
 5→/**
 6→ * Thrown when an operation is attempted on a table handle that has been evicted, closed,
 7→ * or invalidated due to engine shutdown or table drop.
 8→ *
 9→ * <p>
10→ * Carries diagnostic information about the eviction context: the table name, the source
11→ * identifier, the handle count at the time of eviction, the allocation site (if tracking
12→ * was enabled), and the reason for eviction.
13→ *
14→ * <p>
15→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
16→ */
17→public final class HandleEvictedException extends IllegalStateException {
18→
19→    /**
20→     * The reason a handle was evicted.
21→     */
22→    public enum Reason {
23→        /** Handle was evicted due to handle limit pressure. */
24→        EVICTION,
25→        /** Handle was invalidated because the engine was shut down. */
26→        ENGINE_SHUTDOWN,
27→        /** Handle was invalidated because the table was dropped. */
28→        TABLE_DROPPED
29→    }
30→
31→    private final String tableName;
32→    private final String sourceId;
33→    private final int handleCountAtEviction;
34→    private final StackTraceElement[] allocationSite;
35→    private final Reason reason;
36→
37→    /**
38→     * Constructs a new HandleEvictedException.
39→     *
40→     * @param tableName              the name of the table; must not be null
41→     * @param sourceId               the source identifier of the handle; must not be null
42→     * @param handleCountAtEviction  the number of handles open at eviction time
43→     * @param allocationSite         the allocation stack trace, or null if tracking was off
44→     * @param reason                 the reason for eviction; must not be null
45→     */
46→    public HandleEvictedException(String tableName, String sourceId,
47→                                  int handleCountAtEviction,
48→                                  StackTraceElement[] allocationSite,
49→                                  Reason reason) {
50→        super(buildMessage(tableName, sourceId, handleCountAtEviction, reason));
51→        this.tableName = Objects.requireNonNull(tableName, "tableName must not be null");
52→        this.sourceId = Objects.requireNonNull(sourceId, "sourceId must not be null");
53→        this.handleCountAtEviction = handleCountAtEviction;
54→        this.allocationSite = allocationSite;
55→        this.reason = Objects.requireNonNull(reason, "reason must not be null");
56→        assert handleCountAtEviction >= 0 : "handleCountAtEviction must be non-negative";
57→    }
58→
59→    private static String buildMessage(String tableName, String sourceId,
60→                                       int handleCountAtEviction, Reason reason) {
61→        return "Handle evicted: table=" + tableName
62→                + ", source=" + sourceId
63→                + ", openHandles=" + handleCountAtEviction
64→                + ", reason=" + reason;
65→    }
66→
67→    /** Returns the name of the table the handle referenced. */
68→    public String tableName() {
69→        return tableName;
70→    }
71→
72→    /** Returns the source identifier of the evicted handle. */
73→    public String sourceId() {
74→        return sourceId;
75→    }
76→
77→    /** Returns the number of open handles at the time of eviction. */
78→    public int handleCountAtEviction() {
79→        return handleCountAtEviction;
80→    }
81→
82→    /** Returns the allocation site stack trace, or null if tracking was off. */
83→    public StackTraceElement[] allocationSite() {
84→        return allocationSite;
85→    }
86→
87→    /** Returns the reason the handle was evicted. */
88→    public Reason reason() {
89→        return reason;
90→    }
91→}
