  1→package jlsm.table;
  2→
  3→import jlsm.encryption.EncryptionSpec;
  4→
  5→import java.util.Objects;
  6→
  7→/**
  8→ * A document stored in a {@link JlsmTable}, with values ordered according to a {@link JlsmSchema}.
  9→ *
 10→ * <p>
 11→ * Values are stored in schema-field order. A {@code null} entry means the field is absent (PATCH
 12→ * semantics). Type validation is performed eagerly at construction.
 13→ */
 14→public final class JlsmDocument {
 15→
 16→    static {
 17→        jlsm.table.internal.DocumentAccess
 18→                .setAccessor(new jlsm.table.internal.DocumentAccess.Accessor() {
 19→                    @Override
 20→                    public Object[] values(JlsmDocument doc) {
 21→                        return doc.values();
 22→                    }
 23→
 24→                    @Override
 25→                    public JlsmDocument create(jlsm.table.JlsmSchema schema, Object[] values) {
 26→                        return new JlsmDocument(schema, values);
 27→                    }
 28→
 29→                    @Override
 30→                    public boolean isPreEncrypted(JlsmDocument doc) {
 31→                        return doc.isPreEncrypted();
 32→                    }
 33→                });
 34→    }
 35→
 36→    private final JlsmSchema schema;
 37→    private final Object[] values;
 38→    private final boolean preEncrypted;
 39→
 40→    /**
 41→     * Package-private constructor used by the deserializer. Creates a non-pre-encrypted document.
 42→     *
 43→     * @param schema the schema describing the document structure; must not be null
 44→     * @param values values in schema-field order; must not be null
 45→     */
 46→    JlsmDocument(JlsmSchema schema, Object[] values) {
 47→        this(schema, values, false);
 48→    }
 49→
 50→    /**
 51→     * Package-private constructor with explicit pre-encrypted flag.
 52→     *
 53→     * @param schema the schema describing the document structure; must not be null
 54→     * @param values values in schema-field order; must not be null
 55→     * @param preEncrypted whether the document's encrypted fields contain pre-encrypted ciphertext
 56→     */
 57→    JlsmDocument(JlsmSchema schema, Object[] values, boolean preEncrypted) {
 58→        assert schema != null : "schema must not be null";
 59→        assert values != null : "values must not be null";
 60→        assert values.length == schema.fields().size() : "values length must match field count";
 61→        this.schema = schema;
 62→        this.values = values;
 63→        this.preEncrypted = preEncrypted;
 64→    }
 65→
 66→    /**
 67→     * Creates a {@link JlsmDocument} from alternating name/value pairs.
 68→     *
 69→     * <p>
 70→     * Fields not mentioned in {@code nameValuePairs} default to {@code null}. Each value is
 71→     * validated against the declared field type; {@code null} is always accepted (absent field).
 72→     *
 73→     * @param schema the schema describing valid fields; must not be null
 74→     * @param nameValuePairs alternating {@code String name, Object value} pairs
 75→     * @return a new JlsmDocument
 76→     * @throws IllegalArgumentException if a field name is unknown, type is mismatched, or pairs
 77→     *             length is odd
 78→     */
 79→    public static JlsmDocument of(JlsmSchema schema, Object... nameValuePairs) {
 80→        Objects.requireNonNull(schema, "schema must not be null");
 81→        assert nameValuePairs != null : "nameValuePairs must not be null";
 82→        if (nameValuePairs.length % 2 != 0) {
 83→            throw new IllegalArgumentException(
 84→                    "nameValuePairs must be an even number of alternating name/value entries");
 85→        }
 86→
 87→        final Object[] values = new Object[schema.fields().size()];
 88→
 89→        for (int i = 0; i < nameValuePairs.length; i += 2) {
 90→            final Object rawName = nameValuePairs[i];
 91→            if (!(rawName instanceof String fieldName)) {
 92→                throw new IllegalArgumentException(
 93→                        "nameValuePairs entry at index " + i + " must be a String field name");
 94→            }
 95→            final int idx = schema.fieldIndex(fieldName);
 96→            if (idx < 0) {
 97→                throw new IllegalArgumentException("Unknown field: '" + fieldName + "'");
 98→            }
 99→            final Object value = nameValuePairs[i + 1];
100→            if (value != null) {
101→                validateType(fieldName, schema.fields().get(idx).type(), value);
102→            }
103→            values[idx] = value;
104→        }
105→
106→        return new JlsmDocument(schema, values);
107→    }
108→
109→    /**
110→     * Creates a pre-encrypted {@link JlsmDocument} from alternating name/value pairs.
111→     *
112→     * <p>
113→     * Fields with {@code EncryptionSpec != NONE} are expected to hold {@code byte[]} ciphertext
114→     * values (not the declared field type). Fields with {@code EncryptionSpec.NONE} are validated
115→     * normally. {@code null} is always accepted (absent field).
116→     *
117→     * @param schema the schema describing valid fields; must not be null
118→     * @param nameValuePairs alternating {@code String name, Object value} pairs
119→     * @return a new pre-encrypted JlsmDocument
120→     * @throws IllegalArgumentException if a field name is unknown, type is mismatched for an
121→     *             unencrypted field, or pairs length is odd
122→     */
123→    public static JlsmDocument preEncrypted(JlsmSchema schema, Object... nameValuePairs) {
124→        Objects.requireNonNull(schema, "schema must not be null");
125→        assert nameValuePairs != null : "nameValuePairs must not be null";
126→        if (nameValuePairs.length % 2 != 0) {
127→            throw new IllegalArgumentException(
128→                    "nameValuePairs must be an even number of alternating name/value entries");
129→        }
130→
131→        final Object[] values = new Object[schema.fields().size()];
132→
133→        for (int i = 0; i < nameValuePairs.length; i += 2) {
134→            final Object rawName = nameValuePairs[i];
135→            if (!(rawName instanceof String fieldName)) {
136→                throw new IllegalArgumentException(
137→                        "nameValuePairs entry at index " + i + " must be a String field name");
138→            }
139→            final int idx = schema.fieldIndex(fieldName);
140→            if (idx < 0) {
141→                throw new IllegalArgumentException("Unknown field: '" + fieldName + "'");
142→            }
143→            final Object value = nameValuePairs[i + 1];
144→            if (value != null) {
145→                final FieldDefinition fd = schema.fields().get(idx);
146→                if (fd.encryption() instanceof EncryptionSpec.None) {
147→                    // Unencrypted field — validate type normally
148→                    validateType(fieldName, fd.type(), value);
149→                }
150→                // Encrypted fields: accept byte[] ciphertext without type validation
151→            }
152→            values[idx] = value;
153→        }
154→
155→        return new JlsmDocument(schema, values, true);
156→    }
157→
158→    // -------------------------------------------------------------------------
159→    // Typed getters
160→    // -------------------------------------------------------------------------
161→
162→    /** Returns the schema for this document. */
163→    public JlsmSchema schema() {
164→        return schema;
165→    }
166→
167→    /**
168→     * Returns {@code true} if this document was constructed via {@link #preEncrypted} and its
169→     * encrypted fields hold pre-encrypted ciphertext.
170→     */
171→    boolean isPreEncrypted() {
172→        return preEncrypted;
173→    }
174→
175→    /** Returns the raw value array in schema-field order (package-private for serializer use). */
176→    Object[] values() {
177→        return values;
178→    }
179→
180→    /** Returns {@code true} if the field with the given name is null/absent. */
181→    public boolean isNull(String field) {
182→        return values[requireIndex(field)] == null;
183→    }
184→
185→    /** Returns the STRING or BoundedString value of the named field. */
186→    public String getString(String field) {
187→        final int idx = requireIndex(field);
188→        final FieldType actualType = schema.fields().get(idx).type();
189→        if (actualType != FieldType.Primitive.STRING
190→                && !(actualType instanceof FieldType.BoundedString)) {
191→            throw new IllegalArgumentException("Field '" + field + "' has type " + actualType
192→                    + ", not STRING or BoundedString");
193→        }
194→        final Object val = values[idx];
195→        if (val == null) {
196→            throw new NullPointerException("Field '" + field + "' is null");
197→        }
198→        return (String) val;
199→    }
200→
201→    /** Returns the INT8 value of the named field as a {@code byte}. */
202→    public byte getByte(String field) {
203→        return (Byte) requireValue(field, FieldType.Primitive.INT8);
204→    }
205→
206→    /** Returns the INT16 value of the named field as a {@code short}. */
207→    public short getShort(String field) {
208→        return (Short) requireValue(field, FieldType.Primitive.INT16);
209→    }
210→
211→    /** Returns the INT32 value of the named field as an {@code int}. */
212→    public int getInt(String field) {
213→        return (Integer) requireValue(field, FieldType.Primitive.INT32);
214→    }
215→
216→    /**
217→     * Returns the INT64 or TIMESTAMP value of the named field as a {@code long}.
218→     *
219→     * <p>
220→     * Use {@link #getTimestamp(String)} for TIMESTAMP fields if you want self-documenting code.
221→     */
222→    public long getLong(String field) {
223→        final int idx = requireIndex(field);
224→        final FieldType type = schema.fields().get(idx).type();
225→        if (type != FieldType.Primitive.INT64 && type != FieldType.Primitive.TIMESTAMP) {
226→            throw new IllegalArgumentException(
227→                    "Field '" + field + "' is not INT64 or TIMESTAMP, got " + type);
228→        }
229→        return (Long) values[idx];
230→    }
231→
232→    /** Returns the raw IEEE 754 half-precision bits for the FLOAT16 named field. */
233→    public short getFloat16Bits(String field) {
234→        return (Short) requireValue(field, FieldType.Primitive.FLOAT16);
235→    }
236→
237→    /** Returns the FLOAT32 value of the named field as a {@code float}. */
238→    public float getFloat(String field) {
239→        return (Float) requireValue(field, FieldType.Primitive.FLOAT32);
240→    }
241→
242→    /** Returns the FLOAT64 value of the named field as a {@code double}. */
243→    public double getDouble(String field) {
244→        return (Double) requireValue(field, FieldType.Primitive.FLOAT64);
245→    }
246→
247→    /** Returns the BOOLEAN value of the named field. */
248→    public boolean getBoolean(String field) {
249→        return (Boolean) requireValue(field, FieldType.Primitive.BOOLEAN);
250→    }
251→
252→    /** Returns the TIMESTAMP value of the named field as a UTC epoch millisecond {@code long}. */
253→    public long getTimestamp(String field) {
254→        return (Long) requireValue(field, FieldType.Primitive.TIMESTAMP);
255→    }
256→
257→    /** Returns the ARRAY value of the named field. */
258→    public Object[] getArray(String field) {
259→        final int idx = requireIndex(field);
260→        if (!(schema.fields().get(idx).type() instanceof FieldType.ArrayType)) {
261→            throw new IllegalArgumentException("Field '" + field + "' is not an array type");
262→        }
263→        return (Object[]) values[idx];
264→    }
265→
266→    /** Returns the nested document (ObjectType) value of the named field. */
267→    public JlsmDocument getObject(String field) {
268→        final int idx = requireIndex(field);
269→        if (!(schema.fields().get(idx).type() instanceof FieldType.ObjectType)) {
270→            throw new IllegalArgumentException("Field '" + field + "' is not an object type");
271→        }
272→        return (JlsmDocument) values[idx];
273→    }
274→
275→    // -------------------------------------------------------------------------
276→    // JSON / YAML stubs — filled in by later tasks
277→    // -------------------------------------------------------------------------
278→
279→    /** Serializes this document to a compact JSON string. */
280→    public String toJson() {
281→        return new jlsm.table.internal.JsonWriter().write(this, 0);
282→    }
283→
284→    /**
285→     * Serializes this document to a JSON string.
286→     *
287→     * @param pretty {@code true} for pretty-printed output
288→     */
289→    public String toJson(boolean pretty) {
290→        return new jlsm.table.internal.JsonWriter().write(this, pretty ? 2 : 0);
291→    }
292→
293→    /**
294→     * Deserializes a JSON string into a {@link JlsmDocument} conforming to the given schema.
295→     *
296→     * @param json the JSON string; must not be null
297→     * @param schema the target schema; must not be null
298→     * @return a new JlsmDocument
299→     */
300→    public static JlsmDocument fromJson(String json, JlsmSchema schema) {
301→        return new jlsm.table.internal.JsonParser().parse(json, schema);
302→    }
303→
304→    /** Serializes this document to a YAML block-style string. */
305→    public String toYaml() {
306→        return new jlsm.table.internal.YamlWriter().write(this);
307→    }
308→
309→    /**
310→     * Deserializes a YAML string into a {@link JlsmDocument} conforming to the given schema.
311→     *
312→     * @param yaml the YAML string; must not be null
313→     * @param schema the target schema; must not be null
314→     * @return a new JlsmDocument
315→     */
316→    public static JlsmDocument fromYaml(String yaml, JlsmSchema schema) {
317→        return new jlsm.table.internal.YamlParser().parse(yaml, schema);
318→    }
319→
320→    // -------------------------------------------------------------------------
321→    // Internal helpers
322→    // -------------------------------------------------------------------------
323→
324→    private int requireIndex(String field) {
325→        Objects.requireNonNull(field, "field must not be null");
326→        final int idx = schema.fieldIndex(field);
327→        if (idx < 0) {
328→            throw new IllegalArgumentException("Unknown field: '" + field + "'");
329→        }
330→        return idx;
331→    }
332→
333→    private Object requireValue(String field, FieldType expectedType) {
334→        final int idx = requireIndex(field);
335→        final FieldType actualType = schema.fields().get(idx).type();
336→        if (actualType != expectedType) {
337→            throw new IllegalArgumentException(
338→                    "Field '" + field + "' has type " + actualType + ", not " + expectedType);
339→        }
340→        final Object val = values[idx];
341→        if (val == null) {
342→            throw new NullPointerException("Field '" + field + "' is null");
343→        }
344→        return val;
345→    }
346→
347→    /**
348→     * Validates that {@code value} is compatible with {@code type}.
349→     *
350→     * @param fieldName the field name (for error messages)
351→     * @param type the declared field type
352→     * @param value the non-null value to check
353→     * @throws IllegalArgumentException if the value type does not match
354→     */
355→    private static void validateType(String fieldName, FieldType type, Object value) {
356→        assert fieldName != null : "fieldName must not be null";
357→        assert type != null : "type must not be null";
358→        assert value != null : "value must not be null (nulls are handled by callers)";
359→
360→        switch (type) {
361→            case FieldType.Primitive p -> {
362→                switch (p) {
363→                    case STRING -> expect(fieldName, value, String.class, "STRING");
364→                    case INT8 -> expect(fieldName, value, Byte.class, "INT8");
365→                    case INT16 -> expect(fieldName, value, Short.class, "INT16");
366→                    case INT32 -> expect(fieldName, value, Integer.class, "INT32");
367→                    case INT64 -> expect(fieldName, value, Long.class, "INT64");
368→                    case FLOAT16 -> expect(fieldName, value, Short.class, "FLOAT16");
369→                    case FLOAT32 -> expect(fieldName, value, Float.class, "FLOAT32");
370→                    case FLOAT64 -> expect(fieldName, value, Double.class, "FLOAT64");
371→                    case BOOLEAN -> expect(fieldName, value, Boolean.class, "BOOLEAN");
372→                    case TIMESTAMP -> expect(fieldName, value, Long.class, "TIMESTAMP");
373→                }
374→            }
375→            case FieldType.ArrayType _ -> expect(fieldName, value, Object[].class, "ARRAY");
376→            case FieldType.VectorType vt -> {
377→                if (vt.elementType() == FieldType.Primitive.FLOAT32) {
378→                    expect(fieldName, value, float[].class, "VECTOR(FLOAT32)");
379→                    final float[] fArr = (float[]) value;
380→                    if (fArr.length != vt.dimensions()) {
381→                        throw new IllegalArgumentException("Field '" + fieldName
382→                                + "' expects VECTOR(FLOAT32, " + vt.dimensions() + ") but got "
383→                                + fArr.length + " elements");
384→                    }
385→                } else {
386→                    expect(fieldName, value, short[].class, "VECTOR(FLOAT16)");
387→                    final short[] sArr = (short[]) value;
388→                    if (sArr.length != vt.dimensions()) {
389→                        throw new IllegalArgumentException("Field '" + fieldName
390→                                + "' expects VECTOR(FLOAT16, " + vt.dimensions() + ") but got "
391→                                + sArr.length + " elements");
392→                    }
393→                }
394→            }
395→            case FieldType.ObjectType _ -> expect(fieldName, value, JlsmDocument.class, "OBJECT");
396→            case FieldType.BoundedString bs -> {
397→                expect(fieldName, value, String.class, "STRING");
398→                final int byteLen = ((String) value)
399→                        .getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
400→                if (byteLen > bs.maxLength()) {
401→                    throw new IllegalArgumentException(
402→                            "Field '" + fieldName + "' value exceeds BoundedString maxLength "
403→                                    + bs.maxLength() + " (got " + byteLen + " bytes)");
404→                }
405→            }
406→        }
407→    }
408→
409→    private static void expect(String fieldName, Object value, Class<?> expectedClass,
410→            String typeName) {
411→        if (!expectedClass.isInstance(value)) {
412→            throw new IllegalArgumentException("Field '" + fieldName + "' expects " + typeName
413→                    + " (" + expectedClass.getSimpleName() + "), got "
414→                    + value.getClass().getSimpleName());
415→        }
416→    }
417→}
