package jlsm.engine.internal;

import jlsm.engine.HandleEvictedException;
import jlsm.engine.AllocationTracking;
import jlsm.engine.TableMetadata;
import jlsm.table.FieldType;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;
import jlsm.table.JlsmTable;
import jlsm.table.TableEntry;
import jlsm.table.UpdateMode;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.time.Instant;
import java.util.Iterator;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link LocalTable} — verifies delegation, handle validity checks, and null validation.
 *
 * <p>
 * Uses a stub {@link JlsmTable.StringKeyed} to isolate LocalTable logic from the real LSM stack.
 */
class LocalTableTest {

    private JlsmSchema schema;
    private TableMetadata metadata;
    private HandleTracker tracker;
    private StubStringKeyedTable stubDelegate;

    @BeforeEach
    void setUp() {
        schema = JlsmSchema.builder("test", 1)
                .field("id", FieldType.Primitive.STRING)
                .field("value", FieldType.Primitive.STRING)
                .build();
        metadata = new TableMetadata("test_table", schema, Instant.now(), TableMetadata.TableState.READY);
        tracker = HandleTracker.builder()
                .allocationTracking(AllocationTracking.OFF)
                .build();
        stubDelegate = new StubStringKeyedTable();
    }

    private LocalTable createTable() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        return new LocalTable(stubDelegate, reg, tracker, metadata);
    }

    // ---- Constructor null checks ----

    @Test
    void constructorRejectsNullDelegate() {
        final HandleRegistration reg = tracker.register("t", "s");
        assertThrows(NullPointerException.class,
                () -> new LocalTable(null, reg, tracker, metadata));
    }

    @Test
    void constructorRejectsNullRegistration() {
        assertThrows(NullPointerException.class,
                () -> new LocalTable(stubDelegate, null, tracker, metadata));
    }

    @Test
    void constructorRejectsNullTracker() {
        final HandleRegistration reg = tracker.register("t", "s");
        assertThrows(NullPointerException.class,
                () -> new LocalTable(stubDelegate, reg, null, metadata));
    }

    @Test
    void constructorRejectsNullMetadata() {
        final HandleRegistration reg = tracker.register("t", "s");
        assertThrows(NullPointerException.class,
                () -> new LocalTable(stubDelegate, reg, tracker, null));
    }

    // ---- create delegates ----

    @Test
    void createDelegatesToStub() throws IOException {
        try (final LocalTable table = createTable()) {
            final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
            table.create("k1", doc);
            assertTrue(stubDelegate.createCalled, "create should have been called on delegate");
        }
    }

    @Test
    void createRejectsNullKey() {
        try (final LocalTable table = createTable()) {
            final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
            assertThrows(NullPointerException.class, () -> table.create(null, doc));
        }
    }

    @Test
    void createRejectsNullDoc() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class, () -> table.create("k1", null));
        }
    }

    // ---- get delegates ----

    @Test
    void getDelegatesToStub() throws IOException {
        try (final LocalTable table = createTable()) {
            final Optional<JlsmDocument> result = table.get("k1");
            assertTrue(stubDelegate.getCalled, "get should have been called on delegate");
            assertTrue(result.isEmpty());
        }
    }

    @Test
    void getRejectsNullKey() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class, () -> table.get(null));
        }
    }

    // ---- update delegates ----

    @Test
    void updateDelegatesToStub() throws IOException {
        try (final LocalTable table = createTable()) {
            final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
            table.update("k1", doc, UpdateMode.REPLACE);
            assertTrue(stubDelegate.updateCalled, "update should have been called on delegate");
        }
    }

    @Test
    void updateRejectsNullKey() {
        try (final LocalTable table = createTable()) {
            final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
            assertThrows(NullPointerException.class,
                    () -> table.update(null, doc, UpdateMode.REPLACE));
        }
    }

    @Test
    void updateRejectsNullDoc() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class,
                    () -> table.update("k1", null, UpdateMode.REPLACE));
        }
    }

    @Test
    void updateRejectsNullMode() {
        try (final LocalTable table = createTable()) {
            final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
            assertThrows(NullPointerException.class,
                    () -> table.update("k1", doc, null));
        }
    }

    // ---- delete delegates ----

    @Test
    void deleteDelegatesToStub() throws IOException {
        try (final LocalTable table = createTable()) {
            table.delete("k1");
            assertTrue(stubDelegate.deleteCalled, "delete should have been called on delegate");
        }
    }

    @Test
    void deleteRejectsNullKey() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class, () -> table.delete(null));
        }
    }

    // ---- insert extracts primary key and delegates ----

    @Test
    void insertExtractsPrimaryKeyAndDelegates() throws IOException {
        try (final LocalTable table = createTable()) {
            final JlsmDocument doc = JlsmDocument.of(schema, "id", "pk1", "value", "v1");
            table.insert(doc);
            assertTrue(stubDelegate.createCalled, "create should have been called via insert");
            assertEquals("pk1", stubDelegate.lastCreateKey,
                    "insert should extract first field as primary key");
        }
    }

    @Test
    void insertRejectsNullDoc() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class, () -> table.insert(null));
        }
    }

    // ---- query throws UnsupportedOperationException ----

    @Test
    void queryThrowsUnsupportedOperationException() {
        try (final LocalTable table = createTable()) {
            assertThrows(UnsupportedOperationException.class, table::query);
        }
    }

    // ---- scan delegates ----

    @Test
    void scanDelegatesToStub() throws IOException {
        try (final LocalTable table = createTable()) {
            final Iterator<TableEntry<String>> iter = table.scan("a", "z");
            assertTrue(stubDelegate.scanCalled, "scan should have been called on delegate");
            assertNotNull(iter);
        }
    }

    @Test
    void scanRejectsNullFromKey() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class, () -> table.scan(null, "z"));
        }
    }

    @Test
    void scanRejectsNullToKey() {
        try (final LocalTable table = createTable()) {
            assertThrows(NullPointerException.class, () -> table.scan("a", null));
        }
    }

    // ---- metadata returns correct value ----

    @Test
    void metadataReturnsCorrectValue() {
        try (final LocalTable table = createTable()) {
            assertSame(metadata, table.metadata());
        }
    }

    // ---- close releases registration ----

    @Test
    void closeReleasesRegistration() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        // Before close, tracker should have the handle
        assertEquals(1, tracker.snapshot().totalOpenHandles());
        table.close();
        // After close, tracker should have released
        assertEquals(0, tracker.snapshot().totalOpenHandles());
    }

    // ---- evicted handle throws HandleEvictedException on every method ----

    @Test
    void evictedHandleThrowsOnCreate() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
        assertThrows(HandleEvictedException.class, () -> table.create("k1", doc));
    }

    @Test
    void evictedHandleThrowsOnGet() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        assertThrows(HandleEvictedException.class, () -> table.get("k1"));
    }

    @Test
    void evictedHandleThrowsOnUpdate() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
        assertThrows(HandleEvictedException.class,
                () -> table.update("k1", doc, UpdateMode.REPLACE));
    }

    @Test
    void evictedHandleThrowsOnDelete() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        assertThrows(HandleEvictedException.class, () -> table.delete("k1"));
    }

    @Test
    void evictedHandleThrowsOnInsert() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        final JlsmDocument doc = JlsmDocument.of(schema, "id", "k1", "value", "v1");
        assertThrows(HandleEvictedException.class, () -> table.insert(doc));
    }

    @Test
    void evictedHandleThrowsOnQuery() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        assertThrows(HandleEvictedException.class, table::query);
    }

    @Test
    void evictedHandleThrowsOnScan() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        assertThrows(HandleEvictedException.class, () -> table.scan("a", "z"));
    }

    @Test
    void metadataWorksOnEvictedHandle() {
        final HandleRegistration reg = tracker.register("test_table", "test-source");
        reg.invalidate();
        final LocalTable table = new LocalTable(stubDelegate, reg, tracker, metadata);
        // metadata() does NOT check validity
        assertSame(metadata, table.metadata());
    }

    // ---- Stub JlsmTable.StringKeyed ----

    /**
     * Minimal stub that records which methods were called. No real LSM stack.
     */
    private static final class StubStringKeyedTable implements JlsmTable.StringKeyed {

        volatile boolean createCalled;
        volatile boolean getCalled;
        volatile boolean updateCalled;
        volatile boolean deleteCalled;
        volatile boolean scanCalled;
        volatile String lastCreateKey;

        @Override
        public void create(String key, JlsmDocument doc) throws IOException {
            createCalled = true;
            lastCreateKey = key;
        }

        @Override
        public Optional<JlsmDocument> get(String key) throws IOException {
            getCalled = true;
            return Optional.empty();
        }

        @Override
        public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
            updateCalled = true;
        }

        @Override
        public void delete(String key) throws IOException {
            deleteCalled = true;
        }

        @Override
        public Iterator<TableEntry<String>> getAllInRange(String from, String to) throws IOException {
            scanCalled = true;
            return java.util.Collections.emptyIterator();
        }

        @Override
        public void close() throws IOException {
            // no-op
        }
    }
}

package jlsm.engine.internal;

import jlsm.engine.EngineMetrics;
import jlsm.engine.HandleEvictedException;
import jlsm.engine.Table;
import jlsm.engine.TableMetadata;
import jlsm.table.FieldType;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;
import jlsm.table.UpdateMode;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Integration tests for {@link LocalEngine} — uses real temp directories and the full LSM stack.
 */
class LocalEngineTest {

    @TempDir
    Path tempDir;

    private static JlsmSchema testSchema() {
        return JlsmSchema.builder("test", 1)
                .field("id", FieldType.Primitive.STRING)
                .field("value", FieldType.Primitive.STRING)
                .build();
    }

    private LocalEngine buildEngine() throws IOException {
        return buildEngine(tempDir);
    }

    private LocalEngine buildEngine(Path rootDir) throws IOException {
        final LocalEngine engine = LocalEngine.builder()
                .rootDirectory(rootDir)
                .memTableFlushThresholdBytes(4L * 1024 * 1024) // 4 MiB for tests
                .build();
        return engine;
    }

    // ---- Builder validation ----

    @Test
    void builderRequiresRootDirectory() {
        assertThrows(IllegalStateException.class,
                () -> LocalEngine.builder().build());
    }

    @Test
    void builderRejectsNullRootDirectory() {
        assertThrows(NullPointerException.class,
                () -> LocalEngine.builder().rootDirectory(null));
    }

    // ---- createTable ----

    @Test
    void createTableReturnsUsableHandle() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            try (final Table table = engine.createTable("users", testSchema())) {
                assertNotNull(table);
                assertEquals("users", table.metadata().name());
            }
        }
    }

    @Test
    void createTableCreatesDirectoryAndWritesData() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final JlsmSchema schema = testSchema();
            try (final Table table = engine.createTable("users", schema)) {
                final JlsmDocument doc = JlsmDocument.of(schema,
                        "id", "user1", "value", "Alice");
                table.create("user1", doc);

                final Optional<JlsmDocument> found = table.get("user1");
                assertTrue(found.isPresent(), "Document should be retrievable after create");
                assertEquals("Alice", found.get().getString("value"));
            }
        }
    }

    @Test
    void createTableWithDuplicateNameThrowsIOException() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            engine.createTable("users", testSchema()).close();
            assertThrows(IOException.class,
                    () -> engine.createTable("users", testSchema()));
        }
    }

    @Test
    void createTableRejectsNullName() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(NullPointerException.class,
                    () -> engine.createTable(null, testSchema()));
        }
    }

    @Test
    void createTableRejectsEmptyName() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(IllegalArgumentException.class,
                    () -> engine.createTable("", testSchema()));
        }
    }

    @Test
    void createTableRejectsNullSchema() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(NullPointerException.class,
                    () -> engine.createTable("users", null));
        }
    }

    // ---- getTable ----

    @Test
    void getTableReturnsHandleToExistingTable() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final JlsmSchema schema = testSchema();
            try (final Table created = engine.createTable("users", schema)) {
                final JlsmDocument doc = JlsmDocument.of(schema,
                        "id", "user1", "value", "Alice");
                created.create("user1", doc);
            }

            try (final Table retrieved = engine.getTable("users")) {
                assertNotNull(retrieved);
                final Optional<JlsmDocument> found = retrieved.get("user1");
                assertTrue(found.isPresent(),
                        "Data written via createTable should be readable via getTable");
                assertEquals("Alice", found.get().getString("value"));
            }
        }
    }

    @Test
    void getTableForUnknownTableThrowsIOException() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(IOException.class, () -> engine.getTable("nonexistent"));
        }
    }

    @Test
    void getTableRejectsNullName() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(NullPointerException.class, () -> engine.getTable(null));
        }
    }

    @Test
    void getTableRejectsEmptyName() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(IllegalArgumentException.class, () -> engine.getTable(""));
        }
    }

    // ---- dropTable ----

    @Test
    void dropTableRemovesTableAndInvalidatesHandles() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final Table handle = engine.createTable("users", testSchema());
            engine.dropTable("users");
            // After drop, the existing handle should be invalidated
            assertThrows(HandleEvictedException.class, () -> handle.get("k1"));
            // And the table should not be retrievable
            assertThrows(IOException.class, () -> engine.getTable("users"));
        }
    }

    @Test
    void dropTableForUnknownTableThrowsIOException() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(IOException.class, () -> engine.dropTable("nonexistent"));
        }
    }

    @Test
    void dropTableRejectsNullName() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(NullPointerException.class, () -> engine.dropTable(null));
        }
    }

    @Test
    void dropTableRejectsEmptyName() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertThrows(IllegalArgumentException.class, () -> engine.dropTable(""));
        }
    }

    // ---- listTables ----

    @Test
    void listTablesReturnsAllRegisteredTables() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            engine.createTable("users", testSchema()).close();
            engine.createTable("orders", testSchema()).close();

            final Collection<TableMetadata> tables = engine.listTables();
            assertEquals(2, tables.size());
        }
    }

    @Test
    void listTablesReturnsEmptyWhenNoTables() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertTrue(engine.listTables().isEmpty());
        }
    }

    // ---- tableMetadata ----

    @Test
    void tableMetadataReturnsMetadataForKnownTable() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            engine.createTable("users", testSchema()).close();
            final TableMetadata meta = engine.tableMetadata("users");
            assertNotNull(meta);
            assertEquals("users", meta.name());
        }
    }

    @Test
    void tableMetadataReturnsNullForUnknownTable() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            assertNull(engine.tableMetadata("nonexistent"));
        }
    }

    // ---- metrics ----

    @Test
    void metricsReturnCorrectCounts() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final Table t1 = engine.createTable("users", testSchema());
            final Table t2 = engine.createTable("orders", testSchema());

            final EngineMetrics metrics = engine.metrics();
            assertEquals(2, metrics.tableCount());
            assertEquals(2, metrics.totalOpenHandles());

            t1.close();
            t2.close();
        }
    }

    // ---- close invalidates all handles ----

    @Test
    void closeInvalidatesAllHandles() throws IOException {
        final LocalEngine engine = buildEngine();
        final Table handle = engine.createTable("users", testSchema());
        engine.close();
        assertThrows(HandleEvictedException.class, () -> handle.get("k1"));
    }

    // ---- insert and read back data (full pipeline) ----

    @Test
    void fullPipelineInsertAndRead() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final JlsmSchema schema = testSchema();
            try (final Table table = engine.createTable("users", schema)) {
                final JlsmDocument doc = JlsmDocument.of(schema,
                        "id", "user1", "value", "Alice");
                table.insert(doc);

                final Optional<JlsmDocument> found = table.get("user1");
                assertTrue(found.isPresent());
                assertEquals("user1", found.get().getString("id"));
                assertEquals("Alice", found.get().getString("value"));
            }
        }
    }

    @Test
    void fullPipelineDeleteAndVerifyAbsent() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final JlsmSchema schema = testSchema();
            try (final Table table = engine.createTable("users", schema)) {
                final JlsmDocument doc = JlsmDocument.of(schema,
                        "id", "user1", "value", "Alice");
                table.create("user1", doc);
                table.delete("user1");

                final Optional<JlsmDocument> found = table.get("user1");
                assertTrue(found.isEmpty(), "Deleted key should not be found");
            }
        }
    }

    @Test
    void fullPipelineUpdateAndRead() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final JlsmSchema schema = testSchema();
            try (final Table table = engine.createTable("users", schema)) {
                final JlsmDocument doc1 = JlsmDocument.of(schema,
                        "id", "user1", "value", "Alice");
                table.create("user1", doc1);

                final JlsmDocument doc2 = JlsmDocument.of(schema,
                        "id", "user1", "value", "Bob");
                table.update("user1", doc2, UpdateMode.REPLACE);

                final Optional<JlsmDocument> found = table.get("user1");
                assertTrue(found.isPresent());
                assertEquals("Bob", found.get().getString("value"));
            }
        }
    }

    // ---- Engine is usable after restart from same directory ----

    @Test
    void engineRecoversPreviouslyCreatedTables() throws IOException {
        final JlsmSchema schema = testSchema();

        // First engine session: create table and insert data
        try (final LocalEngine engine1 = buildEngine()) {
            try (final Table table = engine1.createTable("users", schema)) {
                final JlsmDocument doc = JlsmDocument.of(schema,
                        "id", "user1", "value", "Alice");
                table.create("user1", doc);
            }
        }

        // Second engine session: recover and read data
        try (final LocalEngine engine2 = buildEngine()) {
            // The table should be discoverable in the catalog
            final Collection<TableMetadata> tables = engine2.listTables();
            assertFalse(tables.isEmpty(), "Restarted engine should discover existing tables");

            // Should be able to get a handle to the recovered table
            try (final Table table = engine2.getTable("users")) {
                assertNotNull(table);
            }
        }
    }

    // ---- Concurrent table creation ----

    @Test
    void concurrentTableCreation() throws Exception {
        try (final LocalEngine engine = buildEngine()) {
            final int threadCount = 4;
            final CyclicBarrier barrier = new CyclicBarrier(threadCount);
            final ExecutorService executor = Executors.newFixedThreadPool(threadCount);

            final List<Future<Table>> futures = new ArrayList<>();
            for (int i = 0; i < threadCount; i++) {
                final int idx = i;
                futures.add(executor.submit(() -> {
                    barrier.await();
                    return engine.createTable("table_" + idx, testSchema());
                }));
            }

            int successCount = 0;
            for (final Future<Table> f : futures) {
                try {
                    final Table t = f.get();
                    t.close();
                    successCount++;
                } catch (Exception e) {
                    // Some may fail due to concurrency; that's fine
                }
            }

            // At least one should succeed; ideally all unique-named ones succeed
            assertTrue(successCount >= 1, "At least some concurrent creates should succeed");
            executor.shutdown();
        }
    }

    // ---- Multiple tables coexist ----

    @Test
    void multipleTablesCoexist() throws IOException {
        try (final LocalEngine engine = buildEngine()) {
            final JlsmSchema schema = testSchema();
            try (final Table users = engine.createTable("users", schema);
                 final Table orders = engine.createTable("orders", schema)) {

                users.create("u1", JlsmDocument.of(schema, "id", "u1", "value", "Alice"));
                orders.create("o1", JlsmDocument.of(schema, "id", "o1", "value", "Order1"));

                assertEquals("Alice", users.get("u1").orElseThrow().getString("value"));
                assertEquals("Order1", orders.get("o1").orElseThrow().getString("value"));

                // Data is isolated between tables
                assertTrue(users.get("o1").isEmpty());
                assertTrue(orders.get("u1").isEmpty());
            }
        }
    }
}

